const apply = () => { document.querySelectorAll('.form-section:not(#section-practitioner) .step').forEach((s, i) => { if (s.textContent !== String(i + 1)) s.textContent = String(i + 1); });
document.querySelectorAll("#section-time .hint").forEach((el) => { const to = {"Showing times with any available practitioner.":"Showing all available times."}[el.textContent.trim()]; if (to !== undefined && el.textContent !== to) el.textContent = to; });
document.querySelectorAll('.summary__row').forEach((r) => { if (r.querySelector('dt')?.textContent.trim() === 'Practitioner') r.remove(); }); };
const mo = new MutationObserver(() => { mo.disconnect(); apply(); mo.observe(document.body, { childList: true, subtree: true, attributes: true }); });
